insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-001', '{"sourceNumber":1,"prompt":"Trong co cơ nhanh, các phân tử ATP được hình thành nhanh chóng nhờ quá trình nào:","options":[{"key":"A","text":"Thu nhận và chuyển hóa glucose từ máu"},{"key":"B","text":"Phân giải glycogen"},{"key":"C","text":"Chuyển nhóm phosphate của phân tử phosphocreatine cho ADP"},{"key":"D","text":"Thu nhận và oxy hóa các acid béo tự do từ máu"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-001', 'C', 'Hệ thống Phosphagen (Phosphocreatine / Creatine phosphate) tái tạo ATP tức thì trong 5–10 giây đầu nhờ enzyme creatine kinase: $\text{Phosphocreatine} + \text{ADP} \rightarrow \text{Creatine} + \text{ATP}$, không cần oxy và không qua chuỗi chuyển hóa enzym phức tạp.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-002', '{"sourceNumber":2,"prompt":"Vai trò đầy đủ của ATP trong tế bào?","options":[{"key":"A","text":"Cung cấp năng lượng cho các phản ứng thoái hoá và tổng hợp các chất"},{"key":"B","text":"Cung cấp, vận chuyển và dự trữ năng lượng"},{"key":"C","text":"Vận chuyển năng lượng"},{"key":"D","text":"Sinh nhiệt"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-002', 'B', 'ATP là đồng tiền năng lượng đảm nhiệm đầy đủ 3 vai trò: Dự trữ năng lượng trong liên kết cao năng, Vận chuyển năng lượng từ ti thể đến các bào quan, và Cung cấp trực tiếp năng lượng cho mọi hoạt động sống.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-003', '{"sourceNumber":3,"prompt":"Nhiệt lượng được định nghĩa như thế nào?:","options":[{"key":"A","text":"Là phần nhiệt năng mà vật nhận được (thu vào) trong quá trình truyền nhiệt"},{"key":"B","text":"Các câu trả lời trên đều không đúng"},{"key":"C","text":"Là phần nhiệt năng mà vật mất đi trong quá trình truyền nhiệt"},{"key":"D","text":"Là phần nhiệt năng mà vật nhận được hay mất đi trong quá trình truyền nhiệt"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-003', 'D', 'Nhiệt lượng ($Q$) là số đo phần năng lượng nhiệt tăng thêm hoặc giảm đi (nhận được hay mất đi) của vật trong quá trình truyền nhiệt.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-004', '{"sourceNumber":4,"prompt":"Biểu thức của nguyên lý thứ nhất nhiệt động lực học được viết dưới dạng:","options":[{"key":"A","text":"$A = F \\cdot S$"},{"key":"B","text":"$\\Delta G = \\Delta H - T\\Delta S$"},{"key":"C","text":"$Q = mc\\Delta T$"},{"key":"D","text":"$\\Delta U = A + Q$"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-004', 'D', 'Theo nguyên lý I nhiệt động học (định luật bảo toàn và chuyển hóa năng lượng), độ biến thiên nội năng $\Delta U$ của hệ bằng tổng công $A$ và nhiệt lượng $Q$ trao đổi với môi trường ngoài.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-005', '{"sourceNumber":5,"prompt":"Đại lượng nào sau đây được dùng để dự đoán hoặc giải thích chiều của một phản ứng phù hợp nhất ở điều kiện nhiệt độ, áp suất không đổi?","options":[{"key":"A","text":"Biến thiên năng lượng tự do Gibbs"},{"key":"B","text":"Biến thiên Enthalpy"},{"key":"C","text":"Năng lượng hoạt hóa"},{"key":"D","text":"Biến thiên Entropy"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-005', 'A', 'Ở điều kiện đẳng nhiệt, đẳng áp ($T, P = \text{const}$), biến thiên năng lượng tự do Gibbs ($\Delta G = \Delta H - T\Delta S$) là tiêu chuẩn nhiệt động quyết định chiều tự phát ($\Delta G < 0$: tự phát theo chiều thuận; $\Delta G = 0$: cân bằng; $\Delta G > 0$: không tự phát theo chiều thuận).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-006', '{"sourceNumber":6,"prompt":"Năng lượng tự do của quá trình vận chuyển thụ động qua màng tế bào có giá trị nào?","options":[{"key":"A","text":"Bằng không"},{"key":"B","text":"Có giá trị âm"},{"key":"C","text":"Tùy từng tình huống"},{"key":"D","text":"Có giá trị dương"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-006', 'B', 'Vận chuyển thụ động là quá trình khuếch tán tự phát xuôi gradient nồng độ/điện hóa, không tiêu tốn ATP. Mọi quá trình tự phát luôn có độ biến thiên năng lượng tự do âm ($\Delta G < 0$).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-007', '{"sourceNumber":7,"prompt":"Chọn phát biểu đúng:","options":[{"key":"A","text":"Enthalpy là một hàm quá trình phụ thuộc vào quá trình diễn biến của hệ"},{"key":"B","text":"Entropy, năng lượng tự do Gibbs là các hàm trạng thái"},{"key":"C","text":"Nội năng của một hệ là hàm quá trình, nhiệt lượng mà hệ trao đổi là hàm trạng thái"},{"key":"D","text":"Công thực hiện, nhiệt lượng trao đổi và nội năng là các hàm quá trình"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-007', 'B', '$U, H, S, G, P, V, T$ là các hàm trạng thái (chỉ phụ thuộc trạng thái đầu và cuối). Trong khi Công ($A$) và Nhiệt lượng ($Q$) là các hàm quá trình (phụ thuộc vào con đường biến đổi).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-008', '{"sourceNumber":8,"prompt":"Khi hệ không sinh công với môi trường ngoài, tổng nhiệt lượng do cơ thể sinh ra được tính như thế nào?","options":[{"key":"A","text":"Gần bằng năng lượng dự trữ dưới dạng hóa năng"},{"key":"B","text":"Gần bằng năng lượng mất mát vào môi trường xung quanh"},{"key":"C","text":"Gần bằng nhiệt lượng sinh ra từ thức ăn-uống đưa vào cơ thể"},{"key":"D","text":"Gần bằng công mà cơ thể chống lại lực của môi trường ngoài"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-008', 'C', 'Theo nguyên lý I áp dụng cho cơ thể sống, khi cơ thể nghỉ ngơi không sinh công cơ học ra ngoài ($A = 0$), toàn bộ hóa năng từ thức ăn đưa vào cơ thể qua chuyển hóa oxy hóa sẽ chuyển thành nhiệt lượng sinh ra.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-009', '{"sourceNumber":9,"prompt":"Tiêu hao năng lượng lớn nhất của cơ thể ở hoạt động nào?","options":[{"key":"A","text":"Tiêu hóa thức ăn"},{"key":"B","text":"Vận chuyển khí và máu"},{"key":"C","text":"Chuyển hóa cơ sở"},{"key":"D","text":"Các hoạt động thể chất (đi lại, chạy, nhảy, làm việc...)"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-009', 'C', 'Chuyển hóa cơ sở (BMR) chiếm tỷ lệ lớn nhất trong tổng năng lượng tiêu hao hàng ngày (khoảng 60% – 75%), trong khi hoạt động thể chất chiếm 20% – 30%, tiêu hóa thức ăn chiếm 8% – 10%.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-010', '{"sourceNumber":10,"prompt":"Theo công thức Mifflin St Jeor, xác định tốc độ chuyển hóa cơ bản (BMR) đối với nam giới 20 tuổi có cân nặng 60 kg, chiều cao 170 cm.","options":[{"key":"A","text":"2000 kcal"},{"key":"B","text":"1567,5 kcal"},{"key":"C","text":"1735,6 kcal"},{"key":"D","text":"2500 kcal"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-010', 'B', '$\text{BMR}_{\text{nam}} = 10 \times m + 6{,}25 \times h - 5 \times \text{tuổi} + 5 = 10 \times 60 + 6{,}25 \times 170 - 5 \times 20 + 5 = 1567{,}5\text{ kcal}$.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-011', '{"sourceNumber":11,"prompt":"Theo công thức Mifflin St Jeor, xác định tốc độ chuyển hóa cơ bản (BMR) đối với nữ giới 20 tuổi có cân nặng 50 kg, chiều cao 160 cm.","options":[{"key":"A","text":"1405 kcal"},{"key":"B","text":"1567,5 kcal"},{"key":"C","text":"1239 kcal"},{"key":"D","text":"1293 kcal"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-011', 'C', '$\text{BMR}_{\text{nữ}} = 10 \times m + 6{,}25 \times h - 5 \times \text{tuổi} - 161 = 10 \times 50 + 6{,}25 \times 160 - 5 \times 20 - 161 = 1239\text{ kcal}$.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-012', '{"sourceNumber":12,"prompt":"Một dược chất có $\\Delta G < 0$ khi hòa tan trong nước. Nhận định nào chính xác nhất?","options":[{"key":"A","text":"Quá trình hòa tan thuận lợi về nhiệt động học nhưng có thể diễn ra chậm"},{"key":"B","text":"Dược chất chắc chắn hòa tan ngay lập tức"},{"key":"C","text":"Tốc độ hòa tan không phụ thuộc vào kích thước tiểu phân"},{"key":"D","text":"Quá trình hòa tan không thể xảy ra"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-012', 'A', '$\Delta G < 0$ khẳng định quá trình hòa tan thuận lợi về nhiệt động học (tự phát), nhưng nhiệt động học không quyết định tốc độ phản ứng (động học). Quá trình có thể diễn ra rất chậm tùy vào năng lượng hoạt hóa và diện tích tiếp xúc.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-013', '{"sourceNumber":13,"prompt":"Trong một quá trình xảy ra ở áp suất không đổi, $\\Delta H < 0$ cho biết quá trình:","options":[{"key":"A","text":"Không trao đổi nhiệt"},{"key":"B","text":"Thu nhiệt"},{"key":"C","text":"Luôn không tự diễn biến"},{"key":"D","text":"Tỏa nhiệt"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-013', 'D', 'Ở áp suất không đổi ($P = \text{const}$), nhiệt phản ứng $Q_p = \Delta H$. Khi $\Delta H < 0$, hệ giải phóng nhiệt lượng ra môi trường $\rightarrow$ Quá trình tỏa nhiệt.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-014', '{"sourceNumber":14,"prompt":"Khi một dược chất rắn hòa tan và các phân tử dược chất phân tán trong dung môi, entropy của hệ thường có xu hướng:","options":[{"key":"A","text":"Luôn giảm mạnh"},{"key":"B","text":"Không bao giờ thay đổi"},{"key":"C","text":"Tăng do các phân tử được phân tán rộng hơn"},{"key":"D","text":"Giảm về bằng không"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-014', 'C', 'Sự hòa tan phá vỡ mạng tinh thể có trật tự cao của chất rắn, các phân tử phân tán tự do trong dung môi làm tăng độ hỗn loạn của hệ $\rightarrow$ Entropy tăng ($\Delta S > 0$).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-015', '{"sourceNumber":15,"prompt":"Đơn vị đo hệ số nhớt của chất lỏng là:","options":[{"key":"A","text":"$\\text{m}^2\\cdot\\text{s}$"},{"key":"B","text":"$\\text{N}\\cdot\\text{m/s}$"},{"key":"C","text":"$\\text{N}\\cdot\\text{s/m}^2$"},{"key":"D","text":"$\\text{m}^2/\\text{s}$"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-015', 'C', 'Theo định luật Newton về nội ma sát: $F = \eta S \frac{dv}{dx} \Rightarrow [\eta] = \frac{\text{N}}{\text{m}^2 \cdot \text{s}^{-1}} = \text{N}\cdot\text{s/m}^2$ (hoặc $\text{Pa}\cdot\text{s}$).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-016', '{"sourceNumber":16,"prompt":"Hai đoạn của một ống dòng nằm ngang có tiết diện là $S_1$ và $S_2$. Muốn vận tốc chảy trong hai đoạn ống này là $v_1 = 2\\text{ m/s}$ và $v_2 = 3\\text{ m/s}$ thì tỉ số giữa $S_1$ và $S_2$ là:","options":[{"key":"A","text":"$S_2/S_1 = 3/2$"},{"key":"B","text":"$S_1/S_2 = 1/2$"},{"key":"C","text":"$S_1/S_2 = 2/3$"},{"key":"D","text":"$S_1/S_2 = 3/2$"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-016', 'D', 'Theo phương trình liên tục của chất lỏng không nén: $S_1 v_1 = S_2 v_2 \Rightarrow \frac{S_1}{S_2} = \frac{v_2}{v_1} = \frac{3}{2}$.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-017', '{"sourceNumber":17,"prompt":"Ảnh hưởng của độ nhớt môi trường phân tán đến hệ nhũ tương thuốc như thế nào?","options":[{"key":"A","text":"Độ nhớt của môi trường phân tán càng lớn thì nhũ tương càng không bền"},{"key":"B","text":"Độ nhớt của môi trường phân tán tăng làm giảm khả năng phân tán của các tiểu phân thuốc"},{"key":"C","text":"Không có ảnh hưởng"},{"key":"D","text":"Độ nhớt của môi trường phân tán càng lớn thì nhũ tương càng bền"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-017', 'D', 'Theo định luật Stokes, vận tốc tách lớp/nổi kem $v = \frac{2r^2(\rho_1-\rho_2)g}{9\eta}$ tỉ lệ nghịch với độ nhớt $\eta$. Môi trường có độ nhớt càng lớn thì các giọt phân tán càng khó chuyển động va chạm kết tụ $\rightarrow$ Nhũ tương càng bền.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-018', '{"sourceNumber":18,"prompt":"Ảnh hưởng của độ nhớt môi trường phân tán đến hệ hỗn dịch thuốc như thế nào?","options":[{"key":"A","text":"Độ nhớt của môi trường phân tán càng nhỏ thì hệ hỗn dịch thuốc càng bền"},{"key":"B","text":"Độ nhớt của môi trường phân tán càng lớn thì tốc độ xa lắng của tiểu phân pha phân tán càng nhỏ"},{"key":"C","text":"Độ nhớt của môi trường phân tán tăng làm tăng khả năng kết tụ của các tiểu phân pha phân tán"},{"key":"D","text":"Không có ảnh hưởng"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-018', 'B', 'Theo định luật Stokes, tốc độ sa lắng tỉ lệ nghịch với độ nhớt của môi trường. Độ nhớt càng lớn thì tốc độ lắng càng nhỏ, hỗn dịch duy trì được trạng thái phân tán đồng đều lâu hơn.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-019', '{"sourceNumber":19,"prompt":"Chọn phát biểu đúng về đặc điểm của áp suất chất lỏng trong một ống dòng nằm ngang:","options":[{"key":"A","text":"Áp suất động tỉ lệ nghịch vận tốc chất lỏng"},{"key":"B","text":"Nơi nào có áp suất động lớn thì áp suất tĩnh nhỏ và ngược lại"},{"key":"C","text":"Áp tĩnh là như nhau tại các điểm có vận tốc chất lỏng khác nhau"},{"key":"D","text":"Áp suất tĩnh tăng khi áp suất động tăng và ngược lại"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-019', 'B', 'Theo định luật Bernoulli: $p + \frac{1}{2}\rho v^2 = \text{const}$. Tổng áp suất tĩnh và áp suất động không đổi, do đó nơi nào vận tốc lớn (áp suất động lớn) thì áp suất tĩnh nhỏ và ngược lại.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-020', '{"sourceNumber":20,"prompt":"Vận chuyển vật chất chủ động qua màng tế bào có đặc điểm sau:","options":[{"key":"A","text":"Từ nơi có thế điện hóa cao xuống nơi có thế điện hóa thấp"},{"key":"B","text":"Ngược chiều gradient nồng độ"},{"key":"C","text":"Theo chiều gradient nồng"},{"key":"D","text":"Từ nơi có nồng độ cao sang nơi có nồng độ thấp"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-020', 'B', 'Vận chuyển chủ động là sự vận chuyển các chất ngược chiều gradient nồng độ (hoặc điện hóa), đòi hỏi tiêu tốn năng lượng ATP và sự tham gia của các protein mang.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-021', '{"sourceNumber":21,"prompt":"Vận chuyển vật chất thụ động qua màng tế bào có đặc điểm sau:","options":[{"key":"A","text":"Cần năng lượng ATP"},{"key":"B","text":"Ngược chiều gradient nồng độ"},{"key":"C","text":"Theo chiều gradient nồng độ"},{"key":"D","text":"Nhờ bơm Na/K-ATPase"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-021', 'C', 'Vận chuyển thụ động diễn ra tự phát theo chiều gradient nồng độ (từ nơi nồng độ cao sang nồng độ thấp), không tiêu tốn năng lượng ATP.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-022', '{"sourceNumber":22,"prompt":"Ở người bình thường, áp suất của tâm thất co trong khoảng:","options":[{"key":"A","text":"50 – 80 Torr"},{"key":"B","text":"20 – 50 Torr"},{"key":"C","text":"120 – 150 Torr"},{"key":"D","text":"160 – 200 Torr"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-022', 'C', 'Trong thời kỳ tâm thu (tâm thất co bóp tống máu), áp suất trong tâm thất trái tăng cao đạt đỉnh khoảng 120 – 150 mmHg (Torr) để mở van tổ chim và bơm máu vào động mạch chủ.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-023', '{"sourceNumber":23,"prompt":"Tính đàn hồi của thành động mạch có nhiệm vụ chính là gì?","options":[{"key":"A","text":"Là thể tích máu do hai tâm thất bơm vào động mạch trong một phút"},{"key":"B","text":"Là thể tích máu nhĩ thu về từ tĩnh mạch"},{"key":"C","text":"Là thể tích máu do một tâm thất bơm vào động mạch trong một lần co bóp"},{"key":"D","text":"Là thể tích máu do một tâm thất bơm vào động mạch trong một phút"}]}'::jsonb, true, 'Đề gốc ghép sai nội dung và đáp án; cần duyệt lại.') on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-023', 'C', 'Đề thi bị ghép nhầm câu hỏi và đáp án. Đáp án C là định nghĩa của Thể tích tâm thu (Stroke Volume); đáp án D là định nghĩa Cung lượng tim (Cardiac Output). Còn nhiệm vụ thực tế của tính đàn hồi là biến đổi dòng máu ngắt quãng thành dòng chảy liên tục.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-024', '{"sourceNumber":24,"prompt":"Những thay đổi sau đây không làm tăng huyết áp:","options":[{"key":"A","text":"Nồng độ O2 trong máu động mạch giảm"},{"key":"B","text":"pH trong máu giảm"},{"key":"C","text":"Nồng độ CO2 trong máu động mạch tăng"},{"key":"D","text":"Nồng độ CO2 trong máu động mạch giảm"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-024', 'D', 'Giảm O2, tăng CO2 hoặc giảm pH (nhiễm toan) kích thích hóa thụ quan làm co mạch, tăng nhịp tim gây tăng huyết áp. Do đó, giảm CO2 không làm tăng huyết áp (gây giãn mạch, hạ/ổn định huyết áp).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-025', '{"sourceNumber":25,"prompt":"Chất lỏng phi Newton có đặc điểm gì?","options":[{"key":"A","text":"Độ nhớt tuân theo định luật Newton về độ nhớt"},{"key":"B","text":"Chất lỏng không có độ nhớt"},{"key":"C","text":"Chất lỏng không có ma sát nội"},{"key":"D","text":"Độ nhớt thay đổi phụ thuộc vào ứng suất, lực tác dụng"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-025', 'D', 'Chất lỏng phi Newton có độ nhớt biểu kiến không cố định mà thay đổi theo ứng suất trượt / lực tác dụng hoặc tốc độ biến dạng (ví dụ: máu toàn phần, dung dịch polymer, hỗn dịch...).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-026', '{"sourceNumber":26,"prompt":"Áp suất khoang màng phổi có đặc điểm nào dưới đây:","options":[{"key":"A","text":"Có giá trị cao hơn áp suất khí quyển ở cuối thì thở ra"},{"key":"B","text":"Có giá trị thấp nhất ở thì hít vào thông thường"},{"key":"C","text":"Làm cho phổi luôn giãn sát với lồng ngực"},{"key":"D","text":"Được tạo ra do tính đàn hồi của lồng ngực"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-026', 'C', 'Áp suất âm trong khoang màng phổi tạo lực hút giữ lá tạng bám sát lá thành, làm phổi luôn giãn sát theo cử động của lồng ngực.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-027', '{"sourceNumber":27,"prompt":"Dung tích sống được xác định như thế nào:","options":[{"key":"A","text":"Là thể tích khí thở ra tối đa sau thở ra bình thường"},{"key":"B","text":"Là thể tích khí thở ra tối đa sau khi hít vào bình thường"},{"key":"C","text":"Là thể tích khí hít vào tối đa sau khi hít vào bình thường"},{"key":"D","text":"Là thể tích khí thở ra tối đa sau hít vào tối đa"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-027', 'D', 'Dung tích sống (VC) là lượng khí tối đa thở ra được sau khi đã hít vào tối đa: $\text{VC} = \text{IRV} + \text{TV} + \text{ERV}$.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-028', '{"sourceNumber":28,"prompt":"Thể tích khí lưu thông được xác định như thế nào:","options":[{"key":"A","text":"Là thể tích khí hít vào tối đa sau khi thở ra bình thường"},{"key":"B","text":"Là thể tích khí thở ra tối đa sau hít vào bình thường"},{"key":"C","text":"Là thể tích khí thở ra hoặc hít vào trong quá trình hít thở bình thường"},{"key":"D","text":"Là thể tích khí thở ra tối đa sau hít vào tối đa"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-028', 'C', 'Thể tích khí lưu thông (TV) là thể tích không khí hít vào hoặc thở ra trong mỗi nhịp thở bình thường, khoảng 400 – 500 mL.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-029', '{"sourceNumber":29,"prompt":"Áp suất âm trong màng phổi có liên quan gì:","options":[{"key":"A","text":"Tạo ra do tính đàn hồi của lồng ngực"},{"key":"B","text":"Làm cho máu lên phổi dễ dàng ở thì thở ra"},{"key":"C","text":"Khiến máu về tim dễ dàng ở thì thở ra"},{"key":"D","text":"Làm cho hiệu suất trao đổi khí đạt giá trị tối đa"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-029', 'D', 'Áp suất âm trong khoang màng phổi giúp phổi nở theo lồng ngực khi hít vào (khí vào phế nang) và đồng thời hút máu tĩnh mạch về tim, giúp máu lên phổi. Nhờ đó thông khí và tưới máu phối hợp tốt, hiệu suất trao đổi khí đạt tối đa. Đây là đáp án phù hợp nhất trong 4 phương án; hai phương án nói "ở thì thở ra" sai vì tác dụng này mạnh ở thì hít vào. *(Lưu ý: đề hơi mơ hồ, nên đối chiếu giáo trình nếu cần.)*') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-030', '{"sourceNumber":30,"prompt":"Oxy từ phế nang vào máu mao mạch phổi theo hình thức nào:","options":[{"key":"A","text":"Khuếch tán thụ động"},{"key":"B","text":"Khuếch tán chủ động"},{"key":"C","text":"Vận chuyển tích cực thứ phát"},{"key":"D","text":"Vận chuyển tích cực qua kẽ tế bào"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-030', 'A', 'Khí oxy và CO2 qua màng phế nang – mao mạch hoàn toàn bằng cơ chế khuếch tán thụ động nhờ chênh lệch phân áp khí (tuân theo định luật Fick).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-031', '{"sourceNumber":31,"prompt":"Khi thêm một chất diện hoạt (chất hoạt động bề mặt) thích hợp vào hỗn dịch thuốc, khả năng phân tán dược chất kỵ nước thường được cải thiện chủ yếu vì:","options":[{"key":"A","text":"Chất diện hoạt làm tăng tỷ trọng của dược chất"},{"key":"B","text":"Chất diện hoạt làm dược chất kết tinh nhanh hơn"},{"key":"C","text":"Chất diện hoạt làm giảm sức căng liên bề mặt giữa dược chất và môi trường phân tán"},{"key":"D","text":"Chất diện hoạt làm tăng kích thước tiểu phân"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-031', 'C', 'Chất diện hoạt làm giảm sức căng liên bề mặt và giảm góc thấm giữa tiểu phân kỵ nước và nước, giúp môi trường thấm ướt bề mặt và phân tán đều các hạt.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-032', '{"sourceNumber":32,"prompt":"Một hỗn dịch uống có tiểu phân dược chất lắng rất nhanh, nhưng dễ phân tán lại khi rung lắc. Biện pháp phù hợp nhất để giảm tốc độ lắng mà vẫn bảo đảm khả năng sử dụng là:","options":[{"key":"A","text":"Tăng kích thước tiểu phân dược chất"},{"key":"B","text":"Thêm một lượng thích hợp chất làm tăng độ nhớt"},{"key":"C","text":"Loại bỏ hoàn toàn nước khỏi công thức"},{"key":"D","text":"Giảm độ nhớt của môi trường phân tán"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-032', 'B', 'Theo định luật Stokes, tốc độ lắng tỉ lệ nghịch với độ nhớt. Thêm chất tăng độ nhớt (chất gây treo) làm tăng $\eta$, giúp giảm tốc độ sa lắng của dược chất.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-033', '{"sourceNumber":33,"prompt":"Trong quá trình bào chế hỗn dịch, bột dược chất nổi trên bề mặt nước và tạo thành các khối vón. Giải pháp phù hợp nhất là gì?","options":[{"key":"A","text":"Đun sôi hỗn dịch trong thời gian dài"},{"key":"B","text":"Tăng kích thước tiểu phân dược chất"},{"key":"C","text":"Bổ sung một lượng lớn chất điện giải bất kỳ"},{"key":"D","text":"Thêm chất diện hoạt thích hợp với nồng độ phù hợp"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-033', 'D', 'Do bột sơ nước có sức căng bề mặt lớn và bám dính bọt khí nên bị nổi vón cục. Bổ sung chất diện hoạt làm chất gây thấm giúp nước làm ướt bột và phân tán vào lòng chất lỏng.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-034', '{"sourceNumber":34,"prompt":"Độ nhớt của chất lỏng phản ánh:","options":[{"key":"A","text":"Khả năng bay hơi của chất lỏng"},{"key":"B","text":"Khả năng làm thay đổi màu sắc của dung dịch"},{"key":"C","text":"Khả năng dẫn điện của chất lỏng"},{"key":"D","text":"Mức độ cản trở sự chảy của chất lỏng"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-034', 'D', 'Độ nhớt (nội ma sát) đặc trưng cho lực cản trở chuyển động trượt giữa các lớp phân tử chất lỏng, tức mức độ cản trở dòng chảy.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-035', '{"sourceNumber":35,"prompt":"Khi chênh lệch nồng độ của một dược chất giữa hai phía của màng tăng, tốc độ khuếch tán của dược chất thường:","options":[{"key":"A","text":"Giảm"},{"key":"B","text":"Tăng"},{"key":"C","text":"Bằng không"},{"key":"D","text":"Không thay đổi"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-035', 'B', 'Theo định luật Fick I: tốc độ khuếch tán tỉ lệ thuận với độ chênh lệch nồng độ $\Delta C$. Do đó $\Delta C$ tăng thì tốc độ khuếch tán tăng.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-036', '{"sourceNumber":36,"prompt":"Khi nhiệt độ tăng trong giới hạn phù hợp, tốc độ khuếch tán của các phân tử trong dung dịch thường:","options":[{"key":"A","text":"Giảm"},{"key":"B","text":"Không thay đổi"},{"key":"C","text":"Tăng"},{"key":"D","text":"Dừng hoàn toàn"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-036', 'C', 'Theo hệ thức Einstein - Stokes: $D = \frac{k_B T}{6\pi \eta r}$. Nhiệt độ tăng làm tăng động năng phân tử và làm giảm độ nhớt $\eta$ của dung môi $\rightarrow$ Tốc độ khuếch tán tăng.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-037', '{"sourceNumber":37,"prompt":"Một dược chất khuếch tán trong siro thường chậm hơn trong nước vì:","options":[{"key":"A","text":"Siro không chứa dung môi"},{"key":"B","text":"Siro có độ nhớt cao hơn nước"},{"key":"C","text":"Siro có màu đậm hơn nước"},{"key":"D","text":"Nước là chất lưu lý tưởng"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-037', 'B', 'Siro có hàm lượng đường rất cao nên độ nhớt lớn hơn nước nhiều lần. Do tốc độ khuếch tán tỉ lệ nghịch với độ nhớt nên dược chất khuếch tán trong siro chậm hơn.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-038', '{"sourceNumber":38,"prompt":"Một dược chất có nồng độ cao trong lòng ruột và nồng độ thấp trong máu. Nếu dược chất có khả năng thấm qua màng ruột bằng khuếch tán thụ động, dược chất sẽ có xu hướng:","options":[{"key":"A","text":"Di chuyển theo hai chiều với tốc độ luôn bằng nhau"},{"key":"B","text":"Di chuyển từ lòng ruột vào máu"},{"key":"C","text":"Di chuyển từ máu vào lòng ruột"},{"key":"D","text":"Không di chuyển qua màng ruột"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-038', 'B', 'Khuếch tán thụ động diễn ra tự phát từ nơi có nồng độ cao đến nơi có nồng độ thấp, tức từ lòng ruột vào máu (quá trình hấp thu thuốc).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-039', '{"sourceNumber":39,"prompt":"Sóng âm có tần số lớn hơn 20 kHz được gọi là:","options":[{"key":"A","text":"Sona"},{"key":"B","text":"Sóng siêu âm"},{"key":"C","text":"Tiếng vang"},{"key":"D","text":"Sóng hạ âm"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-039', 'B', 'Sóng âm có tần số $> 20.000\text{ Hz}$ ($20\text{ kHz}$) vượt ngưỡng nghe của tai người được gọi là sóng siêu âm.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-040', '{"sourceNumber":40,"prompt":"Sóng âm có tần số nhỏ hơn 20 Hz được gọi là:","options":[{"key":"A","text":"Sonar"},{"key":"B","text":"Sóng siêu âm"},{"key":"C","text":"Sóng hạ âm"},{"key":"D","text":"Tiếng vang"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-040', 'C', 'Sóng âm có tần số dưới ngưỡng nghe được của tai người ($< 16 - 20\text{ Hz}$) là sóng hạ âm.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-041', '{"sourceNumber":41,"prompt":"Tốc độ truyền của sóng âm phụ thuộc vào yếu tố nào?","options":[{"key":"A","text":"Duy nhất tần số dao động"},{"key":"B","text":"Duy nhất chu kỳ dao động"},{"key":"C","text":"Mật độ và tính chất đàn hồi của môi trường"},{"key":"D","text":"Khoảng cách đường truyền"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-041', 'C', 'Tốc độ truyền sóng âm chỉ phụ thuộc vào bản chất môi trường (tính đàn hồi $E$, mật độ khối lượng riêng $\rho$, nhiệt độ): $v = \sqrt{E/\rho}$. Không phụ thuộc tần số hay chu kỳ.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-042', '{"sourceNumber":42,"prompt":"Đơn vị đo mức cường độ âm là?","options":[{"key":"A","text":"W"},{"key":"B","text":"$\\text{W/m}^2$"},{"key":"C","text":"dB"},{"key":"D","text":"Hz"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-042', 'C', 'Mức cường độ âm ($L$) đo bằng đơn vị Dexiben (dB) hoặc Ben (B).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-043', '{"sourceNumber":43,"prompt":"Nguồn phát siêu âm không liên quan đến yếu tố sau?","options":[{"key":"A","text":"Hiệu ứng áp điện nghịch/hiện tượng từ giảo"},{"key":"B","text":"Một dụng cụ cung cấp năng lượng dao động"},{"key":"C","text":"Nguồn điện một chiều"},{"key":"D","text":"Một bộ cộng hưởng"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-043', 'C', 'Máy phát siêu âm dùng hiệu ứng áp điện nghịch cần điện trường xoay chiều cao tần để tinh thể co giãn liên tục, không dùng nguồn điện một chiều.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-044', '{"sourceNumber":44,"prompt":"Sự phân biệt âm thanh với hạ âm và siêu âm dựa trên:","options":[{"key":"A","text":"Mức cường độ âm"},{"key":"B","text":"Bản chất vật lý của chúng khác nhau"},{"key":"C","text":"Khả năng cảm thụ sóng cơ của tai người"},{"key":"D","text":"Biên độ dao động của phần tử mà sóng âm lan truyền qua"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-044', 'C', 'Cả ba đều là sóng cơ học lan truyền trong môi trường. Việc phân chia dựa hoàn toàn vào ngưỡng nghe cảm thụ của thính giác người (dưới 16 Hz: hạ âm; 16–20.000 Hz: âm thanh nghe được; trên 20.000 Hz: siêu âm).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-045', '{"sourceNumber":45,"prompt":"Độ to của âm thanh được đặc trưng bằng:","options":[{"key":"A","text":"Áp suất âm thanh"},{"key":"B","text":"Biên độ dao động"},{"key":"C","text":"Mức cường độ âm"},{"key":"D","text":"Tần số âm thanh"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-045', 'C', 'Độ to là đặc trưng sinh lý gắn liền trực tiếp với đặc trưng vật lý là mức cường độ âm ($L$) và tần số âm.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-046', '{"sourceNumber":46,"prompt":"Trong trường hợp nào sau đây tần số sóng âm mà máy thu nhận được lớn hơn tần số sóng âm mà nguồn phát phát ra:","options":[{"key":"A","text":"Máy thu đứng yên so với nguồn phát"},{"key":"B","text":"Máy thu và nguồn phát chuyển động rời xa nhau"},{"key":"C","text":"Máy thu và nguồn phát chuyển động tiến lại gần nhau"},{"key":"D","text":"Nguồn phát chuyển động ra xa máy thu, và máy thu đứng yên"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-046', 'C', 'Theo hiệu ứng Doppler, khi máy thu và nguồn phát chuyển động lại gần nhau thì tần số nhận được tăng lên ($f'' > f$). Khi rời xa nhau thì tần số giảm ($f'' < f$).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-047', '{"sourceNumber":47,"prompt":"Trong siêu âm Doppler, đầu dò thu được sóng âm phản xạ từ các hồng cầu dịch chuyển ra xa đầu dò siêu âm có đặc điểm:","options":[{"key":"A","text":"Tần số thấp hơn tần số sóng siêu âm phát ra"},{"key":"B","text":"Tần số bằng với tần số sóng siêu âm phát ra"},{"key":"C","text":"Không có đáp án nào đúng"},{"key":"D","text":"Tần số lớn hơn tần số sóng siêu âm phát ra"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-047', 'A', 'Khi dòng hồng cầu di chuyển ra xa đầu dò, tần số sóng phản xạ thu về sẽ nhỏ hơn tần số phát ($\Delta f < 0$).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-048', '{"sourceNumber":48,"prompt":"Tác dụng nhiệt của siêu âm trong điều trị không có vai trò nào dưới đây:","options":[{"key":"A","text":"Cho thấy hình ảnh tổn thương"},{"key":"B","text":"Giãn cơ"},{"key":"C","text":"Tăng tuần hoàn máu"},{"key":"D","text":"Thúc đẩy quá trình viêm sớm kết thúc"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-048', 'A', '"Cho thấy hình ảnh tổn thương" là mục đích của siêu âm chẩn đoán hình ảnh, không phải tác dụng nhiệt trong điều trị / vật lý trị liệu.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-049', '{"sourceNumber":49,"prompt":"Trong siêu âm, tín hiệu thu được sau khi đi qua đầu dò là loại nào?","options":[{"key":"A","text":"Tín hiệu điện"},{"key":"B","text":"Tín hiệu siêu âm"},{"key":"C","text":"Tín hiệu âm thanh"},{"key":"D","text":"Tín hiệu quang học"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-049', 'A', 'Khi sóng siêu âm phản xạ từ mô đập vào tinh thể áp điện của đầu dò, nhờ hiệu ứng áp điện thuận, dao động cơ học được biến đổi thành **tín hiệu điện** để đưa về máy tính xử lý và hiển thị hình ảnh.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-050', '{"sourceNumber":50,"prompt":"Siêu âm Doppler không cho phép:","options":[{"key":"A","text":"Hình ảnh cấu trúc bên trong của xương"},{"key":"B","text":"Theo dõi sức khỏe thai nhi"},{"key":"C","text":"Cung cấp thông tin chức năng tim, mạch máu"},{"key":"D","text":"Đánh giá lưu lượng của máu"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-050', 'A', 'Xương có âm trở rất lớn, sóng siêu âm bị phản xạ và hấp thụ gần như hoàn toàn tại bề mặt ngoài tạo bóng cản âm, nên không thể xuyên qua để ghi hình ảnh cấu trúc bên trong của xương (phải dùng X-quang hoặc CT-Scan).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-051', '{"sourceNumber":51,"prompt":"Ứng dụng của sóng siêu âm trong lĩnh vực dược phẩm như phân tán dược chất, chiết xuất thuốc thảo dược nhờ:","options":[{"key":"A","text":"Cung cấp thông tin chi tiết về cấu trúc của phân tử thuốc"},{"key":"B","text":"Cung cấp thông tin về quá trình tương tác của phân tử thuốc với tế bào"},{"key":"C","text":"Sự sụp đổ của bong bóng siêu âm tạo ra sóng xung kích áp suất cao"},{"key":"D","text":"Cung cấp điện năng cho quá trình sản xuất"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-051', 'C', 'Hiện tượng tạo hốc khí (cavitation) làm các bong bóng siêu âm dao động và sụp đổ dữ dội sinh ra sóng xung kích và áp suất cơ học cực cao, giúp phá vỡ màng tế bào dược liệu (tăng hiệu suất chiết xuất) và nghiền nhỏ phân tán đều các hạt dược chất.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-052', '{"sourceNumber":52,"prompt":"Siêu âm có thể được sử dụng trong bào chế nhũ tương nhằm:","options":[{"key":"A","text":"Thay thế chất diện hoạt trong mọi công thức"},{"key":"B","text":"Tách hoàn toàn hai pha dầu và nước"},{"key":"C","text":"Làm tăng kích thước giọt của pha phân tán"},{"key":"D","text":"Làm giảm kích thước giọt và tăng độ đồng nhất của hệ"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-052', 'D', 'Quá trình siêu âm đồng hóa tạo ra các lực xé mạnh mẽ làm giảm kích thước giọt phân tán xuống cấp độ micro/nano mét và phân bố đều vào môi trường, giúp tăng độ đồng nhất và độ bền vững của nhũ tương.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-053', '{"sourceNumber":53,"prompt":"Trong ứng dụng siêu âm vào quá trình chiết hoạt chất từ dược liệu, người ta thấy rằng khi tăng thời gian siêu âm, lượng hoạt chất chiết được tăng trong giai đoạn đầu nhưng giảm khi tiếp tục kéo dài thời gian siêu âm. Nguyên nhân phù hợp với hiện tượng này là:","options":[{"key":"A","text":"Sóng siêu âm làm lượng hoạt chất tăng vô hạn"},{"key":"B","text":"Dược liệu tự động tăng kích thước"},{"key":"C","text":"Siêu âm luôn làm dung môi chuyển thành chất rắn"},{"key":"D","text":"Hoạt chất có thể bị phân hủy do nhiệt hoặc tác động kéo dài của siêu âm"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-053', 'D', 'Ở giai đoạn đầu siêu âm phá vỡ tế bào giúp chiết nhanh hoạt chất; nếu kéo dài quá mức nhiệt lượng tích tụ sinh ra và các gốc tự do từ hiệu ứng hốc khí sẽ làm hoạt chất bị phân hủy hoặc biến tính nhiệt/oxy hóa.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-054', '{"sourceNumber":54,"prompt":"Trong chiết xuất hoạt chất từ dược liệu, siêu âm có thể làm tăng hiệu suất chiết do:","options":[{"key":"A","text":"Loại bỏ hoàn toàn dung môi khỏi hệ chiết tách"},{"key":"B","text":"Làm hoạt chất không thể đi vào dung môi"},{"key":"C","text":"Hỗ trợ phá vỡ cấu trúc tế bào của dược liệu và tăng hiệu quả khuếch tán"},{"key":"D","text":"Làm thành tế bào dược liệu kết tụ và bền vững hơn"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-054', 'C', 'Áp lực cơ học từ sóng siêu âm phá vỡ cấu trúc vách tế bào dược liệu, làm dung môi dễ dàng thẩm thấu sâu và hoạt chất dễ dàng khuếch tán nhanh ra bên ngoài.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-055', '{"sourceNumber":55,"prompt":"Nguyên nhân chủ yếu tạo ra điện thế nghỉ của màng tế bào:","options":[{"key":"A","text":"Các ion (-) trong màng tế bào"},{"key":"B","text":"Khuếch tán ion K+"},{"key":"C","text":"Khuếch tán ion Na+"},{"key":"D","text":"Bơm Na/K - ATPase"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-055', 'D', 'Theo giáo trình môn học, hoạt động của bơm $\text{Na}^+/\text{K}^+$-ATPase vận chuyển tích cực $3\text{ Na}^+$ ra ngoài và đưa $2\text{ K}^+$ vào trong màng tế bào tiêu tốn ATP, tạo ra và duy trì sự chênh lệch nồng độ ion cũng như gradient điện tích qua màng, được xem là nguyên nhân chủ yếu tạo ra điện thế nghỉ.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-056', '{"sourceNumber":56,"prompt":"Yếu tố sau đây **không** tham gia tạo điện thế hoạt động:","options":[{"key":"A","text":"Bơm Na/K - ATPase"},{"key":"B","text":"Mở kênh Na⁺"},{"key":"C","text":"Mở kênh Ca²⁺-Na⁺"},{"key":"D","text":"Mở kênh K⁺"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-056', 'A', 'Điện thế hoạt động hình thành nhờ sự đóng/mở các kênh ion có cổng điện thế: mở kênh Na⁺ gây khử cực, kênh Ca²⁺-Na⁺ tạo pha cao nguyên, kênh K⁺ gây tái cực. Bơm Na/K-ATPase không trực tiếp tạo sóng điện thế hoạt động, chỉ tái lập chênh lệch nồng độ ion sau đó.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-057', '{"sourceNumber":57,"prompt":"Khi xuất hiện điện thế hoạt động, tính thấm của màng đối với ion Na⁺ giảm nhanh trong giai đoạn nào:","options":[{"key":"A","text":"Trong giai đoạn tái phân cực"},{"key":"B","text":"Trong khi quá phân cực"},{"key":"C","text":"Trong giai đoạn tăng nhanh của điện thế hoạt động"},{"key":"D","text":"Trong khi khử cực"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-057', 'A', 'Khi điện thế hoạt động đạt đỉnh, cổng bất hoạt của kênh Na⁺ đóng lại nên tính thấm với Na⁺ giảm nhanh, đồng thời kênh K⁺ mở để đưa điện thế màng trở về mức âm: đó là giai đoạn tái phân cực.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-058', '{"sourceNumber":58,"prompt":"Sự co bóp, hoạt động nhịp nhàng của các ngăn tim được kích thích và điều hòa bởi hệ mô cơ đặc biệt trong tim là:","options":[{"key":"A","text":"Nút xoang nhĩ (SA) và nút nhĩ thất (AV)"},{"key":"B","text":"Bó His và sợi Purkinje"},{"key":"C","text":"Cơ nhĩ và cơ thất"},{"key":"D","text":"Nút xoang nhĩ và mạch vành"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-058', 'A', 'Nút xoang nhĩ là chủ nhịp của tim, nút nhĩ thất tiếp nhận xung và làm chậm dẫn truyền để nhĩ tống máu xuống thất trước khi thất co.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-059', '{"sourceNumber":59,"prompt":"Để ghi điện tim, cần chọn những điểm có đặc điểm gì?","options":[{"key":"A","text":"Trên đường đẳng thế"},{"key":"B","text":"Giữa các điểm mà giữa chúng có hiệu điện thế nhỏ nhất"},{"key":"C","text":"Giữa các điểm mà giữa chúng có hiệu điện thế lớn nhất"},{"key":"D","text":"Tại vị trí bất kỳ gần tim"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-059', 'C', 'Điện tim ghi hiệu điện thế giữa hai điểm trên cơ thể. Chọn các điểm có hiệu điện thế lớn nhất để tín hiệu rõ, biên độ lớn, ít nhiễu. Hai điểm trên cùng đường đẳng thế cho hiệu điện thế bằng 0.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-060', '{"sourceNumber":60,"prompt":"Trong điện não đồ, sóng beta (12-30Hz) thường xuất hiện rõ nét ở người nào?","options":[{"key":"A","text":"Trẻ em dưới 10 tuổi"},{"key":"B","text":"Người lớn khỏe mạnh trong điều kiện thư giãn về giác quan và tinh thần"},{"key":"C","text":"Người luôn hoạt động bận rộn hoặc tâm lý lo lắng hay tập trung cao độ"},{"key":"D","text":"Người đang ngủ sâu hay hôn mê sâu"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-060', 'C', 'Sóng beta tần số cao, biên độ thấp, xuất hiện khi vỏ não hưng phấn, tập trung hoặc lo lắng. Sóng alpha (8–12 Hz): người lớn thư giãn; theta (4–7 Hz): trẻ em hoặc thiu thiu ngủ; delta (0,5–3 Hz): ngủ sâu hoặc hôn mê.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-061', '{"sourceNumber":61,"prompt":"Chọn đáp án đúng:","options":[{"key":"A","text":"Dung môi ít phân cực thì dễ hòa tan các chất không phân cực, khó hòa tan các chất phân cực mạnh"},{"key":"B","text":"Dung môi ít phân cực thì dễ hòa tan các chất phân cực mạnh, khó hòa tan các chất không phân cực"},{"key":"C","text":"Dung môi có hằng số điện môi càng cao thì càng dễ hòa tan các chất không phân cực"},{"key":"D","text":"Dung môi có hằng số điện môi càng thấp thì càng khó hòa tan các chất không phân cực"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-061', 'A', 'Theo nguyên tắc "chất tương tự hòa tan chất tương tự", dung môi ít phân cực (hằng số điện môi thấp) hòa tan tốt chất không phân cực và kém với chất phân cực mạnh.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-062', '{"sourceNumber":62,"prompt":"Các dây thần kinh thị giác được tập trung tại đâu:","options":[{"key":"A","text":"Thủy tinh thể"},{"key":"B","text":"Đồng tử"},{"key":"C","text":"Điểm vàng"},{"key":"D","text":"Điểm mù"}]}'::jsonb, true, 'Đáp án tạm thời; cần hỏi lại giảng viên.') on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-062', 'C', 'Đáp án "Điểm vàng" được chọn tạm thời cho đến khi hỏi lại thầy. Theo giải phẫu, các sợi thần kinh thị giác hội tụ tại điểm mù (đĩa thị) để ra khỏi nhãn cầu, còn điểm vàng là nơi tập trung dày tế bào cảm thụ ánh sáng.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-063', '{"sourceNumber":63,"prompt":"Kĩ thuật chụp cộng hưởng từ là:","options":[{"key":"A","text":"Kỹ thuật dùng trong chẩn đoán y khoa để tạo ra những hình ảnh giải phẫu cơ thể nhờ sóng siêu âm"},{"key":"B","text":"Kỹ thuật dùng trong chẩn đoán y khoa để tạo ra những hình ảnh giải phẫu cơ thể nhờ bức xạ tia X"},{"key":"C","text":"Kỹ thuật dùng trong chẩn đoán y khoa để tạo ra những hình ảnh giải phẫu cơ thể nhờ điện trường và sóng radio"},{"key":"D","text":"Kỹ thuật dùng trong chẩn đoán y khoa để tạo ra những hình ảnh giải phẫu cơ thể nhờ từ trường và sóng radio"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-063', 'D', 'MRI dùng từ trường mạnh để định hướng proton hydro, phát xung sóng radio gây cộng hưởng, thu tín hiệu khi proton hồi phục để dựng hình. Không dùng tia X.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-064', '{"sourceNumber":64,"prompt":"Tìm đáp án mà tất cả các hạt nhân nguyên tử đều **không** được áp dụng trong phương pháp phân tích phổ cộng hưởng từ hạt nhân:","options":[{"key":"A","text":"¹H; ¹³C; ¹⁵N"},{"key":"B","text":"¹⁶O; ¹²C; ³²S"},{"key":"C","text":"³¹P; ¹²C; ³²S"},{"key":"D","text":"²D; ¹²C; ¹⁹F"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-064', 'B', 'Hạt nhân chỉ cho tín hiệu NMR khi spin I ≠ 0. Hạt nhân có số proton và số neutron đều chẵn có I = 0. ¹⁶O, ¹²C, ³²S đều có I = 0. Các hạt nhân ¹H, ¹³C, ¹⁵N, ¹⁹F, ³¹P có I = 1/2; ²D có I = 1.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-065', '{"sourceNumber":65,"prompt":"Ứng dụng của hiện tượng cộng hưởng từ hạt nhân trong lĩnh vực dược phẩm là:","options":[{"key":"A","text":"Kiểm soát chất lượng và phát triển dược phẩm dựa trên các thông tin về tính chất và cấu trúc phân tử"},{"key":"B","text":"Phân tán thuốc dùng năng lượng sóng điện từ"},{"key":"C","text":"Tăng khả năng giải phóng thuốc trong cơ thể nhờ năng lượng sóng cơ"},{"key":"D","text":"Điều chế, sản xuất dược phẩm sử dụng năng lượng sóng cơ học"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-065', 'A', 'NMR xác định cấu trúc phân tử, độ tinh khiết, tạp chất của dược chất nên dùng trong kiểm nghiệm và phát triển thuốc.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-066', '{"sourceNumber":66,"prompt":"Hiện tượng phân cực điện môi là hiện tượng:","options":[{"key":"A","text":"Xuất hiện sự phân bố lại điện tích tự do trên bề mặt thanh điện môi khi đặt trong điện trường"},{"key":"B","text":"Tạo ra các cặp điện tử và lỗ trống khi chiếu ánh sáng thích hợp vào tấm điện môi"},{"key":"C","text":"Xuất hiện các cặp điện tích trái dấu trên thanh điện môi khi nó đặt trong điện trường ngoài"},{"key":"D","text":"Xuất hiện sự phân bố lại điện tích tự do trên bề mặt thanh điện môi khi đặt trong từ trường"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-066', 'C', 'Điện môi không có điện tích tự do. Trong điện trường ngoài, các phân tử bị phân cực nên xuất hiện điện tích liên kết trái dấu ở hai đầu thanh điện môi.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-067', '{"sourceNumber":67,"prompt":"Dược chất ít phân cực thường tan tốt hơn trong:","options":[{"key":"A","text":"Dung môi có tính phân cực tương đồng với dược chất"},{"key":"B","text":"Dung môi có hằng số điện môi cao nhất trong mọi trường hợp"},{"key":"C","text":"Dung môi không có tương tác với dược chất"},{"key":"D","text":"Nước trong mọi điều kiện"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-067', 'A', 'Theo nguyên tắc "chất tương tự hòa tan chất tương tự", dược chất ít phân cực tan tốt trong dung môi có độ phân cực tương đồng (ít phân cực).') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-068', '{"sourceNumber":68,"prompt":"Một dược chất được hòa tan trong hỗn hợp ethanol và nước. Khi thêm một lượng lớn nước, dược chất bị kết tủa. Nguyên nhân phù hợp giải thích hiện tượng này là:","options":[{"key":"A","text":"Ethanol chuyển pha thành chất rắn"},{"key":"B","text":"Dược chất luôn bị phân hủy khi gặp nước"},{"key":"C","text":"Nước làm khối lượng dược chất tăng"},{"key":"D","text":"Môi trường trở nên phân cực hơn, làm giảm độ tan của dược chất ít phân cực"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-068', 'D', 'Thêm nhiều nước làm hỗn hợp dung môi phân cực mạnh hơn, dược chất ít phân cực giảm độ tan nên kết tủa.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-069', '{"sourceNumber":69,"prompt":"Dược chất quá phân cực thường khó khuếch tán thụ động qua lớp lipid của màng tế bào vì:","options":[{"key":"A","text":"Màng tế bào chỉ cho phép các ion kim loại đi qua"},{"key":"B","text":"Dược chất luôn có kích thước lớn"},{"key":"C","text":"Dược chất có ái lực thấp với phần lipid của màng"},{"key":"D","text":"Dược chất phân cực không thể hòa tan trong bất kỳ dung môi nào"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-069', 'C', 'Lõi màng là lớp kép phospholipid kỵ nước. Dược chất quá phân cực ít tan trong lipid nên khó thấm qua màng bằng khuếch tán thụ động.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-070', '{"sourceNumber":70,"prompt":"Tín hiệu điện sinh học ở tế bào chủ yếu được hình thành do:","options":[{"key":"A","text":"Sự phân bố và di chuyển không đồng đều của các ion qua màng tế bào"},{"key":"B","text":"Sự di chuyển của toàn bộ tế bào trong cơ thể"},{"key":"C","text":"Sự thay đổi khối lượng của tế bào"},{"key":"D","text":"Sự chuyển động của các phân tử protein ra khỏi cơ thể"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-070', 'A', 'Điện thế nghỉ, điện thế hoạt động hình thành do chênh lệch nồng độ và sự di chuyển của các ion K⁺, Na⁺, Cl⁻, Ca²⁺ qua màng tế bào.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
insert into public.questions (id, data, active, exclusion_reason) values ('ly-duoc-071', '{"sourceNumber":71,"prompt":"Trong nhiều tế bào động vật ở trạng thái nghỉ, nhận định nào đúng?","options":[{"key":"A","text":"Nồng độ Na⁺ và K⁺ luôn bằng nhau ở trong và ngoài màng"},{"key":"B","text":"Nồng độ K⁺ cao hơn trong tế bào, còn nồng độ Na⁺ cao hơn ngoài tế bào"},{"key":"C","text":"Trong tế bào hoàn toàn không có ion"},{"key":"D","text":"Nồng độ Na⁺ cao hơn trong tế bào, còn K⁺ cao hơn ngoài tế bào"}]}'::jsonb, true, null) on conflict (id) do update set data = excluded.data, active = excluded.active, exclusion_reason = excluded.exclusion_reason;
insert into public.question_answer_keys (question_id, correct_key, explanation) values ('ly-duoc-071', 'B', 'K⁺ tập trung chủ yếu trong tế bào, Na⁺ chủ yếu ngoài tế bào. Sự chênh lệch này được duy trì nhờ bơm Na⁺/K⁺-ATPase.') on conflict (question_id) do update set correct_key = excluded.correct_key, explanation = excluded.explanation;
